"""Maya GLM port, round 29: the prompt (DSA) attention on the XMX engines.  The SYCL port declines every CUDA
tensor-core prompt attention kernel (stubs) and runs the F32 one: dsa_attn = 33% of an 8k prefill.  A new joint_matrix
kernel (fp16 operands, F32 accumulation + online softmax) replaces it in mla_attn unless MAYA_ATTN_XMX=0 or the INT8
latent is on.  Bench (kbench/attn): 3.48x, rel L2 2.2e-4 vs the F32 kernel.  Backups in <raw>/../pre-fix29/.  Idempotent."""
import sys, pathlib, shutil
raw = pathlib.Path(sys.argv[1]); bk = raw.parent / "pre-fix29"; bk.mkdir(exist_ok=True)
p = raw / "src/kernels/cuda/glm_batch.dp.cpp"
t = p.read_text(encoding="utf-8", errors="surrogateescape")
KERNEL = '// SYCL port (fixups29): the prompt attention on the XMX engines (the CUDA tensor-core kernels are stubs in this port).\n// fp16 operands, F32 accumulation and softmax, as the CUDA tc kernels.  Block = (token, 16 heads), 8 sub-groups of 16:\n// Q^T in local memory (fp16, packed B layout); per 32 cells the latent rows in local memory, S^T = L . Q^T on the XMX\n// (sub-group w = cells 8 (w & 3).., K half w >> 2, halves summed in local memory), online softmax (8 lanes a head),\n// P to fp16, O (16 heads x 512 in F32 registers, sub-group w = columns 64 w..) rescaled and O += P . L.\n// kbench/attn (one B70, 1024 tokens x 2051 cells x 64 heads): 97.6 -> 28.0 ms, rel L2 against the F32 kernel 2.2e-4.\nstatic void maya_attn_xmx(sycl::queue& q, const float* q_abs, const uint16_t* lat, const int* cells, const int* n_sel,\n                          int n_sel_max, int NH, float scale, int T, float* ctx) {\n    namespace mx = sycl::ext::oneapi::experimental::matrix;\n    constexpr int KV = 512, AX_HG = 16, AX_CH = 32, AX_LDL = KV + 16;\n    q.submit([&](sycl::handler& h) {\n        sycl::local_accessor<sycl::half, 1> sQT(sycl::range<1>(KV * AX_HG), h);\n        sycl::local_accessor<sycl::half, 1> sL(sycl::range<1>(AX_CH * AX_LDL), h);\n        sycl::local_accessor<float, 1> sS(sycl::range<1>(2 * AX_CH * AX_HG), h);\n        sycl::local_accessor<sycl::half, 1> sP(sycl::range<1>(AX_HG * AX_CH), h);\n        sycl::local_accessor<float, 1> s_m(sycl::range<1>(AX_HG), h), s_l(sycl::range<1>(AX_HG), h), s_sc(sycl::range<1>(AX_HG), h);\n        sycl::local_accessor<int, 1> s_cell(sycl::range<1>(AX_CH), h);\n        h.parallel_for(sycl::nd_range<2>(sycl::range<2>((size_t) T, (size_t) (NH / AX_HG) * 128), sycl::range<2>(1, 128)),\n                       [=](sycl::nd_item<2> it) [[sycl::reqd_sub_group_size(16)]] {\n            const auto sg = it.get_sub_group();\n            const int t = (int) it.get_group(0), h0 = (int) it.get_group(1) * AX_HG, tid = (int) it.get_local_id(1);\n            const int w = (int) sg.get_group_linear_id(), lane = (int) sg.get_local_linear_id();\n            const int ns = n_sel[t];\n            const int* cl = cells + (size_t) t * n_sel_max;\n            // Q^T, packed: element (k, n) at ((k / 2) * 16 + n) * 2 + (k & 1)\n            const float* qa = q_abs + ((size_t) t * NH + h0) * KV;\n            for (int i = tid; i < AX_HG * KV; i += 128) {\n                const int hd = i / KV, k = i - hd * KV;\n                sQT[((k >> 1) * AX_HG + hd) * 2 + (k & 1)] = (sycl::half) qa[i];\n            }\n            if (tid < AX_HG) { s_m[tid] = -INFINITY; s_l[tid] = 0.0f; }\n            mx::joint_matrix<sycl::sub_group, float, mx::use::accumulator, 8, 16> acc[2][4];\n#pragma unroll\n            for (int a = 0; a < 2; ++a)\n#pragma unroll\n                for (int b = 0; b < 4; ++b) mx::joint_matrix_fill(sg, acc[a][b], 0.0f);\n            auto pL = sL.template get_multi_ptr<sycl::access::decorated::no>();\n            auto pQ = sQT.template get_multi_ptr<sycl::access::decorated::no>();\n            auto pP = sP.template get_multi_ptr<sycl::access::decorated::no>();\n            const int mt = w & 3, ks = w >> 2;\n            for (int s0 = 0; s0 < ns; s0 += AX_CH) {\n                it.barrier(sycl::access::fence_space::local_space);\n                if (tid < AX_CH) s_cell[tid] = s0 + tid < ns ? cl[s0 + tid] : -1;\n                it.barrier(sycl::access::fence_space::local_space);\n                for (int i = tid; i < AX_CH * (KV / 8); i += 128) {\n                    const int s = i >> 6, c = i & 63;\n                    const int cell = s_cell[s];\n                    *(sycl::uint4*) &sL[s * AX_LDL + c * 8] =\n                        cell < 0 ? sycl::uint4(0u, 0u, 0u, 0u) : ((const sycl::uint4*) (lat + (size_t) KV * cell))[c];\n                }\n                it.barrier(sycl::access::fence_space::local_space);\n                {   // S^T partial: cells 8 mt.., K half ks\n                    mx::joint_matrix<sycl::sub_group, float, mx::use::accumulator, 8, 16> c;\n                    mx::joint_matrix_fill(sg, c, 0.0f);\n#pragma unroll 4\n                    for (int kk = 0; kk < 16; ++kk) {\n                        const int k0 = ks * 256 + kk * 16;\n                        mx::joint_matrix<sycl::sub_group, sycl::half, mx::use::a, 8, 16, mx::layout::row_major> ma;\n                        mx::joint_matrix<sycl::sub_group, sycl::half, mx::use::b, 16, 16, mx::layout::ext_intel_packed> mb;\n                        mx::joint_matrix_load(sg, ma, pL + (8 * mt) * AX_LDL + k0, AX_LDL);\n                        mx::joint_matrix_load(sg, mb, pQ + (k0 / 2) * AX_HG * 2, AX_HG * 2);\n                        mx::joint_matrix_mad(sg, c, ma, mb, c);\n                    }\n                    auto wd = sycl::ext::oneapi::detail::get_wi_data(sg, c);   // lane = head, element i = cell 8 mt + i\n#pragma unroll\n                    for (int i = 0; i < 8; ++i) sS[(ks * AX_CH + 8 * mt + i) * AX_HG + lane] = (float) wd[i];\n                }\n                it.barrier(sycl::access::fence_space::local_space);\n                {   // online softmax: head tid >> 3, cells 4 (tid & 7)..+3\n                    const int hd = tid >> 3, g = tid & 7;\n                    float v[4], mxv = -INFINITY;\n#pragma unroll\n                    for (int j = 0; j < 4; ++j) {\n                        const int c = 4 * g + j;\n                        v[j] = s_cell[c] < 0 ? -INFINITY : (sS[c * AX_HG + hd] + sS[(AX_CH + c) * AX_HG + hd]) * scale;\n                        mxv = sycl::fmax(mxv, v[j]);\n                    }\n                    const float m_old = s_m[hd];\n#pragma unroll\n                    for (int o = 1; o < 8; o <<= 1) mxv = sycl::fmax(mxv, sycl::permute_group_by_xor(sg, mxv, o));\n                    const float m_new = sycl::fmax(m_old, mxv);\n                    float sum = 0.0f;\n#pragma unroll\n                    for (int j = 0; j < 4; ++j) {\n                        const float e = v[j] == -INFINITY ? 0.0f : sycl::native::exp(v[j] - m_new);\n                        sum += e;\n                        sP[hd * AX_CH + 4 * g + j] = (sycl::half) e;\n                    }\n#pragma unroll\n                    for (int o = 1; o < 8; o <<= 1) sum += sycl::permute_group_by_xor(sg, sum, o);\n                    if (g == 0) {\n                        const float sc = m_old == -INFINITY ? 0.0f : sycl::native::exp(m_old - m_new);\n                        s_sc[hd] = sc; s_l[hd] = s_l[hd] * sc + sum; s_m[hd] = m_new;\n                    }\n                }\n                it.barrier(sycl::access::fence_space::local_space);\n                // O (heads x columns 64 w..) *= scale per head; O += P . L\n#pragma unroll\n                for (int a = 0; a < 2; ++a) {\n                    float sc[8];\n#pragma unroll\n                    for (int i = 0; i < 8; ++i) sc[i] = s_sc[8 * a + i];\n#pragma unroll\n                    for (int b = 0; b < 4; ++b) {\n                        auto wd = sycl::ext::oneapi::detail::get_wi_data(sg, acc[a][b]);   // element i = head 8 a + i\n#pragma unroll\n                        for (int i = 0; i < 8; ++i) wd[i] = (float) wd[i] * sc[i];\n                    }\n                }\n#pragma unroll\n                for (int kk = 0; kk < 2; ++kk) {\n                    mx::joint_matrix<sycl::sub_group, sycl::half, mx::use::a, 8, 16, mx::layout::row_major> pa0, pa1;\n                    mx::joint_matrix_load(sg, pa0, pP + 0 * AX_CH + 16 * kk, AX_CH);\n                    mx::joint_matrix_load(sg, pa1, pP + 8 * AX_CH + 16 * kk, AX_CH);\n#pragma unroll\n                    for (int b = 0; b < 4; ++b) {\n                        mx::joint_matrix<sycl::sub_group, sycl::half, mx::use::b, 16, 16, mx::layout::row_major> lb;\n                        mx::joint_matrix_load(sg, lb, pL + (16 * kk) * AX_LDL + 64 * w + 16 * b, AX_LDL);\n                        mx::joint_matrix_mad(sg, acc[0][b], pa0, lb, acc[0][b]);\n                        mx::joint_matrix_mad(sg, acc[1][b], pa1, lb, acc[1][b]);\n                    }\n                }\n            }\n            it.barrier(sycl::access::fence_space::local_space);\n#pragma unroll\n            for (int a = 0; a < 2; ++a) {\n                float inv[8];\n#pragma unroll\n                for (int i = 0; i < 8; ++i) { const float L = s_l[8 * a + i]; inv[i] = L > 0.0f ? 1.0f / L : 0.0f; }\n#pragma unroll\n                for (int b = 0; b < 4; ++b) {\n                    auto wd = sycl::ext::oneapi::detail::get_wi_data(sg, acc[a][b]);\n#pragma unroll\n                    for (int i = 0; i < 8; ++i) wd[i] = (float) wd[i] * inv[i];\n                    float* o = ctx + ((size_t) t * NH + h0 + 8 * a) * KV + 64 * w + 16 * b;\n                    mx::joint_matrix_store(sg, acc[a][b],\n                                           sycl::address_space_cast<sycl::access::address_space::global_space, sycl::access::decorated::no>(o),\n                                           KV, mx::layout::row_major);\n                }\n            }\n        });\n    });\n}\n\n'
DISPATCH = '    // SYCL port (fixups29): the XMX kernel (MAYA_ATTN_XMX=0: the F32 one); the INT8 latent stays on the F32 kernel\n    static const bool xmx_attn = [] {\n        const char* e = std::getenv("MAYA_ATTN_XMX");\n        const bool on = e == nullptr || e[0] != \'0\';\n        std::fprintf(stderr, "glm_batch: prompt attention on the %s\\n", on ? "XMX engines (fp16, fixups29)" : "F32 cores");\n        return on;\n    }();\n    if (xmx_attn && !lat_q8 && n_head % 16 == 0) {\n        maya_attn_xmx(*s, q_abs, lat, cells, n_sel, n_sel_max, n_head, scale, T, ctx);\n        return;\n    }\n'
anchor = "void mla_attn(const float *q_abs, const uint16_t *lat, const int *cells,"
check = """        std::fprintf(stderr, "glm_batch mla_attn: kv_lora %d / n_head %d unsupported\\n", kv_lora, n_head);
        return;
    }
"""
if "fixups29" not in t:
    assert t.count(anchor) == 1, t.count(anchor)
    assert t.count(check) == 1, t.count(check)
    shutil.copy(p, bk / "glm_batch.dp.cpp")
    t = t.replace(anchor, KERNEL + anchor, 1)
    t = t.replace(check, check + DISPATCH, 1)
    p.write_text(t, encoding="utf-8", errors="surrogateescape"); print("  prompt attention on XMX (MAYA_ATTN_XMX)")
else: print("  already")
